   * @param {object} record Internal entry record.
   * @returns {Readonly<object>} Frozen view.
   */
  #refresh(record) {
    const view = Object.freeze({
      id: record.id,
      at: record.at,
      seq: record.seq,
      memo: record.memo,
      lines: Object.freeze(record.lines.map((line) => Object.freeze({ account: line.account, amountCents: line.amountCents }))),
      reverses: record.reverses,
      reversedBy: record.reversedBy,
    });
    this.#views.set(record.id, view);
    return view;
  }

  /**
   * Post a balanced entry.
   *
   * @param {{id: string, at: number, memo?: string, lines: Array<{account: string, amountCents: number}>}} entry Entry to post.
   * @returns {Readonly<object>} The stored entry.
   */
  post(entry) {
    if (typeof entry !== 'object' || entry === null) {
      throw new LedgerError('BAD_ENTRY', 'entry must be an object');
    }
    const { id, at, memo = '', lines } = entry;
    if (typeof id !== 'string' || id === '') {
      throw new LedgerError('BAD_ENTRY', 'entry id must be a non-empty string');
    }
    if (this.#entries.has(id)) throw new LedgerError('DUPLICATE_ENTRY', `entry already exists: ${id}`);
    if (typeof at !== 'number' || !Number.isInteger(at) || at < 0) {
      throw new LedgerError('BAD_TIME', 'entry time must be a non-negative integer');
    }
    if (typeof memo !== 'string') throw new LedgerError('BAD_ENTRY', 'entry memo must be a string');
    if (!Array.isArray(lines) || lines.length < 2) {
      throw new LedgerError('TOO_FEW_LINES', 'entry must have at least two lines');
    }
    let sum = 0;
    const copied = [];
    for (const line of lines) {
      const account = line === null || typeof line !== 'object' ? undefined : line.account;
      if (typeof account !== 'string' || !this.#accounts.has(account)) {
        throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${account}`);
      }
      const { amountCents } = line;
      if (typeof amountCents !== 'number' || !Number.isSafeInteger(amountCents)) {
        throw new LedgerError('NOT_INTEGER', 'line amountCents must be a safe integer');
      }
      if (amountCents === 0) throw new LedgerError('ZERO_LINE', 'line amountCents must not be zero');
      sum += amountCents;
      copied.push({ account, amountCents });
    }
    if (sum !== 0) throw new LedgerError('UNBALANCED', 'entry lines must sum to zero');

    this.#seq += 1;
    const record = {
      id,
      at,
      seq: this.#seq,
      memo,
      lines: copied,
      reverses: entry.reverses === undefined ? null : entry.reverses,
      reversedBy: null,
    };
    this.#entries.set(id, record);
    this.#order.push(record);
    return this.#refresh(record);
  }

  /**
   * Look up an entry.
   *
   * @param {string} id Entry id.
   * @returns {Readonly<object>|undefined} The entry, if it exists.
   */
  getEntry(id) {
    return this.#views.get(id);
  }

  /**
   * Internal records up to a moment, ordered by time then posting order.
   *
   * @param {number} asOf Cut-off, inclusive.
   * @returns {Array<object>} Matching records.
   */
  #upTo(asOf) {
    return this.#order
      .filter((record) => record.at <= asOf)
      .sort((left, right) => (left.at - right.at) || (left.seq - right.seq));
  }

  /**
   * Entries up to a moment, oldest first.
   *
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {Array<Readonly<object>>} Matching entries ordered by time then posting order.
   */
  entries(options = {}) {
    const asOf = checkTime(options?.asOf, 'asOf', Infinity);
    return this.#upTo(asOf).map((record) => this.#views.get(record.id));
  }

  /**
   * Debit-positive balance of one account.
   *
   * @param {string} accountId Account to measure.
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {number} Signed balance in cents.
   */
  balance(accountId, options = {}) {
    if (!this.#accounts.has(accountId)) {
      throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${accountId}`);
    }
    const asOf = checkTime(options?.asOf, 'asOf', Infinity);
    let total = 0;
    for (const record of this.#order) {
      if (record.at > asOf) continue;
      for (const line of record.lines) {
        if (line.account === accountId) total += line.amountCents;
      }
    }
    return total;
  }

  /**
   * Balance of one account in its own normal direction.
   *
   * @param {string} accountId Account to measure.
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {number} Balance in cents, positive when on the normal side.
   */
  normalBalance(accountId, options = {}) {
    const signed = this.balance(accountId, options);
    return toNormal(this.#accounts.get(accountId).type, signed);
  }

  /**
   * Debit and credit totals across every account.
   *
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {{debits: number, credits: number, byAccount: Record<string, number>}} Trial balance.
   */
  trialBalance(options = {}) {
    const asOf = checkTime(options?.asOf, 'asOf', Infinity);
    const byAccount = {};
    let debits = 0;
    let credits = 0;
    for (const account of this.accounts()) {
      const value = this.balance(account.id, { asOf });
